window.NOTEBOOK_FULL_EXAMS = {"llm-06a": {"chapterId": "llm-06a", "title": "06A · Classification Finetuning · 전체 노트북 시험", "file": "Chapter_6_Finetuning_for_Text_Classification_KR.ipynb", "instruction": "전체 노트북을 위에서 아래로 읽고, 각 빈칸이 요구하는 코드만 작성하세요. 답은 빈칸 번호 순서대로 독립적으로 채점됩니다.", "cells": [{"cell_number": 4, "source": "from importlib.metadata import version\n\npkgs = [\"matplotlib\",  # 그래프 라이브러리\n        \"numpy\",       # 파이토치와 텐서플로의 종속성\n        \"tiktoken\",    # 토크나이저\n        \"torch\",       # 딥러닝 라이브러리\n        # \"tensorflow\",  # OpenAI의 사전 훈련된 가중치를 위해서\n        \"pandas\"       # 데이터셋 로딩을 위해\n       ]\nfor p in pkgs:\n    print(f\"{p} 버전: {version(p)}\")"}, {"cell_number": 14, "source": "import requests\nimport zipfile\nimport os\nfrom pathlib import Path\n\nurl = \"https://archive.ics.uci.edu/static/public/228/sms+spam+collection.zip\"\nzip_path = \"datas/sms_spam_collection.zip\"\nextracted_path = \"datas/sms_spam_collection\"\ndata_file_path = Path(extracted_path) / \"SMSSpamCollection.tsv\"\n\n\ndef download_and_unzip_spam_data(url, zip_path, extracted_path, data_file_path):\n    if data_file_path.exists():\n        print(f\"{data_file_path}가 이미 있어 다운로드 및 압축 해제를 건너뜁니다.\")\n        return\n\n    # 파일을 다운로드 합니다.\n    response = requests.get(url, stream=True, timeout=60)\n    response.raise_for_status()\n    with open(zip_path, \"wb\") as out_file:\n        for chunk in response.iter_content(chunk_size=8192):\n            if chunk:\n                out_file.write(chunk)\n\n    # 파일 압축을 풉니다.\n    with zipfile.ZipFile(zip_path, \"r\") as zip_ref:\n        zip_ref.extractall(extracted_path)\n\n    # .tsv 파일 확장자를 추가합니다.\n    original_file_path = Path(extracted_path) / \"SMSSpamCollection\"\n    os.rename(original_file_path, data_file_path)\n    print(f\"파일이 다운로드되어 {data_file_path}에 저장되었습니다.\")\n\ntry:\n    download_and_unzip_spam_data(url, zip_path, extracted_path, data_file_path)\nexcept (requests.exceptions.RequestException, TimeoutError) as e:\n    print(f\"기본 URL 실패: {e}. 백업 URL을 시도합니다...\")\n    url = \"https://f001.backblazeb2.com/file/LLMs-from-scratch/sms%2Bspam%2Bcollection.zip\"\n    download_and_unzip_spam_data(url, zip_path, extracted_path, data_file_path)"}, {"cell_number": 16, "source": "import pandas as pd\n\ndf = pd.read_csv(data_file_path, sep=\"\\t\", header=None, names=[\"Label\", \"Text\"])\ndf"}, {"cell_number": 18, "source": "print(df[\"Label\"].value_counts())"}, {"cell_number": 20, "source": "def create_balanced_dataset(df):\n\n    # \"스팸\" 샘플 개수 세기\n    num_spam = df[df[\"Label\"] == \"spam\"].shape[0]\n\n    # \"스팸\" 샘플 개수와 일치하도록 \"햄\" 샘플을 무작위로 샘플링\n    ham_subset = df[df[\"Label\"] == \"ham\"].sample(num_spam, random_state=123)\n\n    # \"햄\"과 \"스팸\"을 합침\n    balanced_df = pd.concat([ham_subset, df[df[\"Label\"] == \"spam\"]])\n\n    return balanced_df\n\n\nbalanced_df = create_balanced_dataset(df)\nprint(balanced_df[\"Label\"].value_counts())"}, {"cell_number": 22, "source": "balanced_df[\"Label\"] = balanced_df[\"Label\"].map({\"ham\": 0, \"spam\": 1})"}, {"cell_number": 23, "source": "balanced_df"}, {"cell_number": 25, "source": "import pandas as pd\n\ndef random_split(df, train_frac, validation_frac):\n    \"\"\"\n    데이터프레임을 학습, 검증, 테스트 세트로 무작위 분할하는 함수\n    \n    Args:\n        df: 분할할 전체 데이터프레임\n        train_frac: 학습 데이터 비율 (예: 0.7)\n        validation_frac: 검증 데이터 비율 (예: 0.1)\n        # 테스트 데이터 비율은 남은 비율로 자동 결정됩니다.\n    \"\"\"\n    \n    # 1. 데이터프레임 전체 섞기 (Shuffle)\n    # - frac=1: 전체 데이터의 100%를 샘플링 (모든 데이터를 가져오되 순서만 섞음)\n    # - random_state=123: 매번 실행할 때마다 똑같은 순서로 섞이도록 고정 (재현성 확보)\n    # - reset_index(drop=True): 섞인 후 뒤죽박죽된 인덱스를 버리고, 0부터 다시 차례대로 부여\n    df = df.sample(frac=1, random_state=123).reset_index(drop=True)\n\n    # 2. 분할할 지점(인덱스 위치) 계산\n    # 전체 개수(len)에 비율을 곱해 어디서 자를지 정수형(int)으로 계산\n    train_end = int(len(df) * train_frac)                          # 학습 데이터가 끝나는 지점\n    validation_end = train_end + int(len(df) * validation_frac)    # 검증 데이터가 끝나는 지점\n\n    # 3. 데이터프레임 슬라이싱 (Slicing)으로 분할\n    train_df = df[:train_end]                     # 처음부터 ~ 학습 끝 지점까지\n    validation_df = df[train_end:validation_end]  # 학습 끝 지점부터 ~ 검증 끝 지점까지\n    test_df = df[validation_end:]                 # 검증 끝 지점부터 ~ 마지막 끝까지 (나머지 전부)\n\n    return train_df, validation_df, test_df\n\n# 함수 실행 예시\n# balanced_df라는 데이터를 7:1:2 비율로 나눕니다.\n# (Train: 70%, Validation: 10%, Test: 나머지 20%)\ntrain_df, validation_df, test_df = random_split(balanced_df, 0.7, 0.1)\n\n# 4. 결과 저장 (CSV 파일 생성)\n# index=None: 저장할 때 불필요한 인덱스 번호(0, 1, 2...)는 파일에 포함하지 않음\ntrain_df.to_csv(\"datas/train.csv\", index=None)\nvalidation_df.to_csv(\"datas/validation.csv\", index=None)\ntest_df.to_csv(\"datas/test.csv\", index=None)"}, {"cell_number": 29, "source": "import tiktoken\n\ntokenizer = tiktoken.get_encoding(\"gpt2\")\nprint(tokenizer.encode(\"<|endoftext|>\", allowed_special={\"<|endoftext|>\"}))"}, {"cell_number": 31, "source": "import torch\nfrom torch.utils.data import Dataset\nimport pandas as pd  # 데이터프레임 사용을 위해 pandas 임포트 필요\n\nclass SpamDataset(Dataset):\n    \"\"\"\n    CSV 파일의 텍스트 데이터를 읽어 토큰화, 자르기, 패딩을 수행하여\n    PyTorch 모델에 입력 가능한 형태로 변환하는 데이터셋 클래스\n    \"\"\"\n    def __init__(self, csv_file, tokenizer, max_length=None, pad_token_id=50256):\n        # 1. 데이터 로드: pandas를 사용하여 CSV 파일을 읽어옵니다.\n        self.data = pd.read_csv(csv_file)\n\n        # 2. 토큰화 (Tokenization):\n        # 데이터프레임의 \"Text\" 컬럼에 있는 모든 문장을 하나씩 꺼내서\n        # tokenizer.encode()를 통해 정수 리스트(숫자)로 변환합니다.\n        self.encoded_texts = [\n            tokenizer.encode(text) for text in self.data[\"Text\"]\n        ]\n\n        # 3. 최대 길이(max_length) 결정 로직:\n        if max_length is None:\n            # 사용자가 길이를 지정하지 않았다면, 데이터 중 가장 긴 문장의 길이를 사용\n            self.max_length = self._longest_encoded_length()\n        else:\n            # 사용자가 길이를 지정했다면 그 값을 사용하고,\n            self.max_length = max_length\n            # 지정된 길이보다 긴 문장은 뒷부분을 잘라냅니다 (Truncation).\n            self.encoded_texts = ????  # [빈칸 01]\n\n        # 4. 패딩 (Padding):\n        # 모든 문장의 길이를 self.max_length로 통일합니다.\n        # 문장 길이가 max_length보다 짧다면, 부족한 만큼 pad_token_id로 채웁니다.\n        # 예: 문장 [10, 20], max=4, pad=0 -> [10, 20, 0, 0]\n        self.encoded_texts = ????  # [빈칸 02]\n\n    def __getitem__(self, index):\n        \"\"\"\n        데이터셋에서 특정 인덱스(index)의 샘플을 가져오는 함수\n        데이터 로더(DataLoader)가 배치를 만들 때 이 함수를 반복 호출합니다.\n        \"\"\"\n        encoded = self.encoded_texts[index]\n        label = ????  # [빈칸 03]\n\n        # 파이토치 모델은 '텐서(Tensor)' 형태만 입력받을 수 있으므로 변환합니다.\n        # dtype=torch.long은 정수형(인덱스, 라벨 등)을 의미합니다.\n        return (\n            torch.tensor(encoded, dtype=torch.long),\n            torch.tensor(label, dtype=torch.long)\n        )\n\n    def __len__(self):\n        # 데이터셋의 전체 샘플 개수를 반환 (학습 시 에포크 계산 등에 사용됨)\n        return len(self.data)\n\n    def _longest_encoded_length(self):\n        # 데이터셋 내의 모든 문장 중 가장 긴 문장의 길이를 찾는 헬퍼 함수\n        max_length = 0\n        for encoded_text in self.encoded_texts:\n            encoded_length = len(encoded_text)\n            if encoded_length > max_length:\n                max_length = encoded_length\n        return max_length\n        \n        # (참고) 파이썬의 max() 함수를 쓰면 위 6줄을 한 줄로 줄일 수 있습니다:\n        # return max(len(encoded_text) for encoded_text in self.encoded_texts)"}, {"cell_number": 32, "source": "train_dataset = SpamDataset(\n    csv_file=\"datas/train.csv\",\n    max_length=None,\n    tokenizer=tokenizer\n)\n\nprint(train_dataset.max_length)"}, {"cell_number": 34, "source": "val_dataset = SpamDataset(\n    csv_file=\"datas/validation.csv\",\n    max_length=train_dataset.max_length,\n    tokenizer=tokenizer\n)\ntest_dataset = SpamDataset(\n    csv_file=\"datas/test.csv\",\n    max_length=train_dataset.max_length,\n    tokenizer=tokenizer\n)"}, {"cell_number": 37, "source": "from torch.utils.data import DataLoader\n\nnum_workers = 0\nbatch_size = 8\n\ntorch.manual_seed(123)\n\ntrain_loader = DataLoader(\n    dataset=train_dataset,\n    batch_size=batch_size,\n    shuffle=True, #학습할 때는 shuffle가 중요\n    num_workers=num_workers,\n    drop_last=True, #미지막을 버릴지 말지\n)\n\nval_loader = DataLoader(\n    dataset=val_dataset,\n    batch_size=batch_size,\n    num_workers=num_workers,\n    drop_last=False,\n)\n\ntest_loader = DataLoader(\n    dataset=test_dataset,\n    batch_size=batch_size,\n    num_workers=num_workers,\n    drop_last=False,\n)"}, {"cell_number": 39, "source": "print(\"훈련 세트 로더:\")\nfor input_batch, target_batch in train_loader:\n    pass\n\nprint(\"입력 배치 차원:\", input_batch.shape)\nprint(\"레이블 배치 차원\", target_batch.shape)"}, {"cell_number": 41, "source": "print(f\"{len(train_loader)}개 훈련 배치\")\nprint(f\"{len(val_loader)}개 검증 배치\")\nprint(f\"{len(test_loader)}개 테스트 배치\")"}, {"cell_number": 44, "source": "CHOOSE_MODEL = \"gpt2-small (124M)\"\nINPUT_PROMPT = \"Every effort moves\"\n\nBASE_CONFIG = {\n    \"vocab_size\": 50257,     # 어휘사전 크기\n    \"context_length\": 1024,  # 문맥 길이\n    \"drop_rate\": 0.0,        # 드롭아웃 비율\n    \"qkv_bias\": True         # 쿼리-키-값 편향\n}\n\nmodel_configs = {\n    \"gpt2-small (124M)\": {\"emb_dim\": 768, \"n_layers\": 12, \"n_heads\": 12}, #트랜스포머 블록(Transformer Block)을 몇 층으로 쌓아 올렸는지\n    \"gpt2-medium (355M)\": {\"emb_dim\": 1024, \"n_layers\": 24, \"n_heads\": 16},\n    \"gpt2-large (774M)\": {\"emb_dim\": 1280, \"n_layers\": 36, \"n_heads\": 20},\n    \"gpt2-xl (1558M)\": {\"emb_dim\": 1600, \"n_layers\": 48, \"n_heads\": 25},\n}\n\nBASE_CONFIG.update(model_configs[CHOOSE_MODEL])\n\nassert train_dataset.max_length <= BASE_CONFIG[\"context_length\"], (\n    f\"데이터셋 길이 {train_dataset.max_length}가 모델의 문맥 \"\n    f\"길이 {BASE_CONFIG['context_length']}를 초과합니다. `max_length={BASE_CONFIG['context_length']}`로 \"\n    f\"데이터 셋을 다시 초기화하십시오.\"\n)"}, {"cell_number": 45, "source": "from previous_chapters import GPTModel, load_gpt2_model\n\nmodel_name = \"gpt2-small-124M.pth\"\nmodel = load_gpt2_model(model_name, BASE_CONFIG)\nmodel.eval()"}, {"cell_number": 47, "source": "from previous_chapters import (\n    generate_text_simple,\n    text_to_token_ids,\n    token_ids_to_text\n)\n\n\ntext_1 = \"Every effort moves you\"\n\ntoken_ids = generate_text_simple(\n    model=model,\n    idx=text_to_token_ids(text_1, tokenizer),\n    max_new_tokens=15,\n    context_size=BASE_CONFIG[\"context_length\"]\n)\n\nprint(token_ids_to_text(token_ids, tokenizer))"}, {"cell_number": 49, "source": "text_2 = (\n    \"Is the following text 'spam'? Answer with 'yes' or 'no':\"\n    \" 'You are a winner you have been specially\"\n    \" selected to receive $1000 cash or a $2000 award.'\"\n)\n\ntoken_ids = generate_text_simple(\n    model=model,\n    idx=text_to_token_ids(text_2, tokenizer),\n    max_new_tokens=23,\n    context_size=BASE_CONFIG[\"context_length\"]\n)\n\nprint(token_ids_to_text(token_ids, tokenizer))"}, {"cell_number": 55, "source": "for param in model.parameters():\n    param.requires_grad = ????  # [빈칸 04]"}, {"cell_number": 57, "source": "torch.manual_seed(123)\n\nnum_classes = 2\nmodel.out_head = ????  # [빈칸 05]"}, {"cell_number": 63, "source": "# 1. 마지막 트랜스포머 블록의 파라미터 잠금 해제\n# model.trf_blocks[-1]: 트랜스포머 블록 리스트 중 '가장 마지막(-1)' 블록을 선택\nfor param in model.trf_blocks[-1].parameters():\n    # requires_grad = True:\n    # 이 파라미터(가중치)에 대해 기울기(Gradient)를 계산하도록 설정합니다.\n    # 즉, 역전파(Backpropagation) 때 이 가중치를 '업데이트(학습)' 하겠다는 뜻입니다.\n    param.requires_grad = ????  # [빈칸 06]\n\n# 2. 마지막 정규화(Normalization) 층의 파라미터 잠금 해제\n# 모델의 최종 출력 직전에 있는 LayerNorm 층도 학습 대상에 포함시킵니다.\nfor param in model.final_norm.parameters():\n    # 마찬가지로 이 층의 가중치도 학습되도록 설정합니다.\n    param.requires_grad = ????  # [빈칸 07]"}, {"cell_number": 65, "source": "inputs = tokenizer.encode(\"Do you have time\")\ninputs = torch.tensor(inputs).unsqueeze(0)\nprint(\"입력:\", inputs)\nprint(\"입력 차원:\", inputs.shape) # shape: (배치 크기, 토큰 수)"}, {"cell_number": 67, "source": "with torch.no_grad():\n    outputs = model(inputs)\n\nprint(\"출력:\\n\", outputs)\nprint(\"출력 차원:\", outputs.shape) # shape: (배치 크기, 토큰 수, 클래스 수)"}, {"cell_number": 71, "source": "print(\"마지막 출력 토큰:\", outputs[:, -1, :])"}, {"cell_number": 78, "source": "probas = torch.softmax(outputs[:, -1, :], dim=-1)\nlabel = torch.argmax(probas)\nprint(\"클래스 레이블:\", label.item())"}, {"cell_number": 80, "source": "logits = outputs[:, -1, :]\nlabel = torch.argmax(logits)\nprint(\"클래스 레이블:\", label.item())"}, {"cell_number": 82, "source": "import torch\n\ndef calc_accuracy_loader(data_loader, model, device, num_batches=None):\n    \"\"\"\n    데이터 로더를 순회하며 모델의 정확도를 계산하는 함수\n    \"\"\"\n    # 1. 평가 모드 전환 (매우 중요)\n    # Dropout이나 Batch Normalization 같이 학습 때만 동작해야 하는 기능들을 비활성화합니다.\n    model.eval()\n    \n    correct_predictions, num_examples = 0, 0\n\n    # 2. 평가할 배치 개수 설정\n    # num_batches가 없으면 전체 데이터를, 있으면 지정된 개수만큼만 확인합니다 (빠른 테스트용).\n    if num_batches is None:\n        num_batches = len(data_loader)\n    else:\n        num_batches = min(num_batches, len(data_loader))\n        \n    # 3. 데이터 로더 순회 (enumerate로 인덱스 i와 데이터를 같이 받음)\n    for i, (input_batch, target_batch) in enumerate(data_loader):\n        # 지정된 배치 개수까지만 반복\n        if i < num_batches:\n            # 데이터를 GPU(또는 지정된 device)로 이동\n            input_batch, target_batch = input_batch.to(device), target_batch.to(device)\n\n            # 4. 기울기(Gradient) 계산 비활성화 context\n            # 평가만 할 것이므로 역전파를 위한 기록을 하지 않아 메모리를 아끼고 속도를 높입니다.\n            with torch.no_grad():\n                # 모델 예측 수행\n                # 결과 shape 가정: (Batch_Size, Sequence_Length, Num_Classes)\n                # [:, -1, :] -> 모든 배치의(:), 가장 마지막 토큰(-1)의, 모든 클래스 확률(:)을 가져옴\n                logits = model(input_batch)[:, -1, :] \n            \n            # 5. 예측값 결정\n            # dim=-1: 가장 마지막 차원(클래스 확률)에서 가장 큰 값의 인덱스(클래스 번호)를 찾음\n            predicted_labels = torch.argmax(logits, dim=-1)\n\n            # 6. 정확도 누적 계산\n            # 현재 배치의 데이터 개수 더하기\n            num_examples += predicted_labels.shape[0]\n            # 예측값과 정답이 같은지 비교(==)하여 True(1)의 개수(.sum)를 더함\n            correct_predictions += (predicted_labels == target_batch).sum().item()\n        else:\n            break\n            \n    # 전체 맞은 개수 / 전체 데이터 개수 = 정확도\n    return correct_predictions / num_examples"}, {"cell_number": 84, "source": "devices = {param.device for param in model.parameters()}\nprint(devices)"}, {"cell_number": 86, "source": "if torch.cuda.is_available():\n    device = torch.device(\"cuda\")\nelse:\n    device = torch.device(\"cpu\")\n\nprint(f\"실행 장치: {device}\")\n\nmodel.to(device) # nn.Module 클래스의 경우 model = model.to(device) 할당문이 필요하지 않습니다.\n\ntorch.manual_seed(123) # 데이터 로더에서 셔플링하기 때문에 재현성을 위해\n\ntrain_accuracy = calc_accuracy_loader(train_loader, model, device, num_batches=10)\nval_accuracy = calc_accuracy_loader(val_loader, model, device, num_batches=10)\ntest_accuracy = calc_accuracy_loader(test_loader, model, device, num_batches=10)\n\nprint(f\"훈련 정확도: {train_accuracy*100:.2f}%\")\nprint(f\"검증 정확도: {val_accuracy*100:.2f}%\")\nprint(f\"테스트 정확도: {test_accuracy*100:.2f}%\")"}, {"cell_number": 89, "source": "import torch\n\ndef calc_loss_batch(input_batch, target_batch, model, device):\n    \"\"\"\n    배치 단위로 모델의 손실(Loss)을 계산하는 함수\n    \"\"\"\n    # 1. 데이터를 연산 장치(GPU 또는 CPU)로 이동\n    input_batch, target_batch = input_batch.to(device), target_batch.to(device)\n\n    # 2. 모델 예측 (Forward Pass)\n    # logits shape: [배치 크기, 문장 길이, 단어 집합 크기(Vocab Size)]\n    logits = model(input_batch)\n\n    # 3. 손실 계산 방식 분기 (중요!)\n    # target_batch의 차원 수(dim)를 확인하여 작업 종류를 구분합니다.\n    \n    # CASE A: 단순 분류 (Sequence Classification)\n    # 정답(target)이 [0, 1, 0] 처럼 1차원인 경우 (각 문장마다 정답이 하나)\n    if target_batch.dim() == 1:\n        # 문장의 '가장 마지막 토큰'의 예측값(logits[:, -1, :])만 사용하여\n        # 정답과 비교해 손실을 계산합니다.\n        loss = ????  # [빈칸 08]\n        \n    # CASE B: 언어 모델링 (Language Modeling / Next Token Prediction)\n    # 정답이 [[10, 20], [30, 40]] 처럼 2차원인 경우 (모든 단어 위치마다 정답이 존재)\n    else:\n        # 모델 출력과 정답을 일렬로 쭉 폅니다(Flatten).\n        # logits: [배치*길이, 단어집합크기], target: [배치*길이]\n        # 이렇게 모양을 맞춰줘야 CrossEntropy가 모든 단어에 대해 오차를 평균 낼 수 있습니다.\n        loss = ????  # [빈칸 09]\n\n    return loss"}, {"cell_number": 91, "source": "# 5장과 동일\ndef calc_loss_loader(data_loader, model, device, num_batches=None):\n    total_loss = 0.\n    if len(data_loader) == 0:\n        return float(\"nan\")\n    elif num_batches is None:\n        num_batches = len(data_loader)\n    else:\n        # num_batches가 데이터 로더의 배치 수를 초과하는 경우\n        # 데이터 로더의 총 배치 수와 일치하도록 배치 수를 줄입니다.\n        num_batches = min(num_batches, len(data_loader))\n    for i, (input_batch, target_batch) in enumerate(data_loader):\n        if i < num_batches:\n            loss = calc_loss_batch(input_batch, target_batch, model, device)\n            total_loss += loss.item()\n        else:\n            break\n    return total_loss / num_batches"}, {"cell_number": 93, "source": "with torch.no_grad(): # 효율성을 위해 그레이디언트 추적을 비활성화합니다. 아직 훈련하지 않기 때문입니다.\n    train_loss = calc_loss_loader(train_loader, model, device, num_batches=5)\n    val_loss = calc_loss_loader(val_loader, model, device, num_batches=5)\n    test_loss = calc_loss_loader(test_loader, model, device, num_batches=5)\n\nprint(f\"훈련 손실: {train_loss:.3f}\")\nprint(f\"검증 손실: {val_loss:.3f}\")\nprint(f\"테스트 손실: {test_loss:.3f}\")"}, {"cell_number": 98, "source": "import torch\n\n# 5장의 `train_model_simple`과 구조가 거의 같지만, 분류(Classification)를 위해 일부 수정된 함수\ndef train_classifier_simple(model, train_loader, val_loader, optimizer, device, num_epochs,\n                            eval_freq, eval_iter):\n    \"\"\"\n    모델을 학습시키고, 주기적으로 검증 데이터로 성능을 평가하는 함수\n    \n    Args:\n        model: 학습할 파이토치 모델\n        train_loader: 학습 데이터 공급자 (DataLoader)\n        val_loader: 검증 데이터 공급자 (DataLoader)\n        optimizer: 가중치를 업데이트하는 최적화 도구 (예: AdamW)\n        device: 학습을 진행할 장치 (CPU or GPU)\n        num_epochs: 전체 데이터를 몇 번 반복해서 학습할지\n        eval_freq: 몇 번의 스텝(배치)마다 손실을 출력할지 설정\n        eval_iter: 평가 시 몇 개의 배치만 사용할지 (속도를 위해 일부만 사용 가능)\n    \"\"\"\n    \n    # 1. 기록용 리스트 초기화 (나중에 그래프를 그리기 위해 저장)\n    train_losses, val_losses, train_accs, val_accs = [], [], [], []\n    examples_seen, global_step = 0, -1\n\n    # 2. 메인 학습 루프 (에포크 단위 반복)\n    for epoch in range(num_epochs):\n        model.train()  # 중요: 모델을 '학습 모드'로 전환 (Dropout 등이 켜짐)\n\n        # 3. 배치 단위 반복 (데이터 로더에서 배치를 하나씩 꺼냄)\n        for input_batch, target_batch in train_loader:\n            optimizer.zero_grad() # (a) 기울기 초기화: 이전 배치의 계산 찌꺼기 제거\n            \n            # (b) 손실(Loss) 계산: 모델이 예측하고, 정답과 비교하여 오차 계산\n            loss = calc_loss_batch(input_batch, target_batch, model, device)\n            \n            # (c) 역전파(Backpropagation): 오차를 줄이는 방향(기울기) 계산\n            loss.backward() \n            \n            # (d) 가중치 업데이트: 계산된 방향으로 모델 파라미터 수정\n            optimizer.step() \n\n            # 진행 상황 추적\n            examples_seen += input_batch.shape[0] # 몇 개의 데이터를 봤는지 누적\n            global_step += 1\n\n            # 4. 중간 평가 단계 (eval_freq 스텝마다 실행)\n            # 학습 중간중간에 손실(Loss)이 잘 줄어들고 있는지 확인\n            if global_step % eval_freq == 0:\n                # evaluate_model 함수를 호출하여 현재 상태의 손실 계산\n                train_loss, val_loss = evaluate_model(\n                    model, train_loader, val_loader, device, eval_iter)\n                \n                train_losses.append(train_loss)\n                val_losses.append(val_loss)\n                \n                print(f\"에포크 {epoch+1} (Step {global_step:06d}): \"\n                      f\"훈련 손실 {train_loss:.3f}, 검증 손실 {val_loss:.3f}\")\n\n        # 5. 에포크 종료 후 정확도(Accuracy) 계산\n        # 손실(Loss)만으로는 직관적이지 않으므로, '몇 퍼센트 맞췄는지' 확인\n        train_accuracy = calc_accuracy_loader(train_loader, model, device, num_batches=eval_iter)\n        val_accuracy = calc_accuracy_loader(val_loader, model, device, num_batches=eval_iter)\n        \n        print(f\"훈련 정확도: {train_accuracy*100:.2f}% | \", end=\"\")\n        print(f\"검증 정확도: {val_accuracy*100:.2f}%\")\n        \n        train_accs.append(train_accuracy)\n        val_accs.append(val_accuracy)\n\n    return train_losses, val_losses, train_accs, val_accs, examples_seen"}, {"cell_number": 100, "source": "# 5장과 동일\n# 모델의 손실을 평가하는 헬퍼 함수\ndef evaluate_model(model, train_loader, val_loader, device, eval_iter):\n    model.eval()  # 중요: 모델을 '평가 모드'로 전환 (Dropout 등이 꺼짐)\n    \n    # 평가 시에는 기울기 계산을 하지 않음 (메모리 절약, 속도 향상)\n    with torch.no_grad():\n        train_loss = calc_loss_loader(train_loader, model, device, num_batches=eval_iter)\n        val_loss = calc_loss_loader(val_loader, model, device, num_batches=eval_iter)\n    \n    model.train() # 평가가 끝나면 다시 '학습 모드'로 복구\n    \n    return train_loss, val_loss"}, {"cell_number": 102, "source": "import time\n\nstart_time = time.time()\n\ntorch.manual_seed(123)\n\noptimizer = torch.optim.AdamW(model.parameters(), lr=5e-5, weight_decay=0.1)\n\nnum_epochs = 5\ntrain_losses, val_losses, train_accs, val_accs, examples_seen = train_classifier_simple(\n    model, train_loader, val_loader, optimizer, device,\n    num_epochs=num_epochs, eval_freq=50, eval_iter=5,\n)\n\nend_time = time.time()\nexecution_time_minutes = (end_time - start_time) / 60\nprint(f\"훈련 소요 시간: {execution_time_minutes:.2f}분\")"}, {"cell_number": 104, "source": "import matplotlib.pyplot as plt\n\ndef plot_values(epochs_seen, examples_seen, train_values, val_values, label=\"loss\"):\n    fig, ax1 = plt.subplots(figsize=(5, 3))\n\n    # 훈련 및 검증 손실을 에포크에 따라 그립니다.\n    ax1.plot(epochs_seen, train_values, label=f\"Training {label}\")\n    ax1.plot(epochs_seen, val_values, linestyle=\"-.\", label=f\"Validation {label}\")\n    ax1.set_xlabel(\"Epochs\")\n    ax1.set_ylabel(label.capitalize())\n    ax1.legend()\n\n    # 처리한 샘플 수를 위해 두 번째 x축을 만듭니다.\n    ax2 = ax1.twiny()  # 동일한 y축을 공유하는 두 번째 x축을 만듭니다.\n    ax2.plot(examples_seen, train_values, alpha=0)  # 눈금 정렬을 위한 보이지 않는 그래프\n    ax2.set_xlabel(\"Examples seen\")\n\n    fig.tight_layout()  # 공간을 확보하기 위해 레이아웃을 조정합니다.\n    plt.savefig(f\"outputs/{label}-plot.pdf\")\n    plt.show()"}, {"cell_number": 105, "source": "epochs_tensor = torch.linspace(0, num_epochs, len(train_losses))\nexamples_seen_tensor = torch.linspace(0, examples_seen, len(train_losses))\n\nplot_values(epochs_tensor, examples_seen_tensor, train_losses, val_losses)"}, {"cell_number": 107, "source": "epochs_tensor = torch.linspace(0, num_epochs, len(train_accs))\nexamples_seen_tensor = torch.linspace(0, examples_seen, len(train_accs))\n\nplot_values(epochs_tensor, examples_seen_tensor, train_accs, val_accs, label=\"accuracy\")"}, {"cell_number": 109, "source": "train_accuracy = calc_accuracy_loader(train_loader, model, device)\nval_accuracy = calc_accuracy_loader(val_loader, model, device)\ntest_accuracy = calc_accuracy_loader(test_loader, model, device)\n\nprint(f\"훈련 정확도: {train_accuracy*100:.2f}%\")\nprint(f\"검증 정확도: {val_accuracy*100:.2f}%\")\nprint(f\"테스트 정확도: {test_accuracy*100:.2f}%\")"}, {"cell_number": 114, "source": "import torch\n\ndef classify_review(text, model, tokenizer, device, max_length=None, pad_token_id=50256):\n    \"\"\"\n    단일 텍스트(리뷰)를 입력받아 스팸 여부를 분류하는 함수\n    \"\"\"\n    # 1. 평가 모드 설정\n    # 학습이 아니므로 Dropout 등을 비활성화하여 일관된 결과를 얻습니다.\n    model.eval()\n\n    # 2. 텍스트 토큰화 (Encoding)\n    # 문자열(text)을 모델이 이해하는 정수 리스트(input_ids)로 변환합니다.\n    input_ids = tokenizer.encode(text)\n    \n    # 모델이 물리적으로 처리할 수 있는 최대 길이 확인 (예: GPT-2는 보통 1024)\n    supported_context_length = model.pos_emb.weight.shape[0]\n\n    # 3. 시퀀스 자르기 (Truncation)\n    # 입력이 너무 길면 모델이 처리할 수 없으므로 잘라냅니다.\n    # 사용자가 설정한 max_length와 모델 한계치 중 더 작은 값으로 길이를 제한합니다.\n    # 주의: 아래 코드는 max_length가 None일 경우 에러가 날 수 있으므로, assert문으로 방어합니다.\n    input_ids = input_ids[:min(max_length, supported_context_length)]\n    \n    # (안전장치) max_length가 올바르게 설정되었는지 확인\n    assert max_length is not None, (\n        \"max_length가 지정되지 않았습니다. 모델의 최대 문맥 길이를 사용하려면 \"\n        \"max_length=model.pos_emb.weight.shape[0]로 지정하세요.\"\n    )\n    assert max_length <= supported_context_length, (\n        f\"max_length({max_length})가 모델이 지원하는 문맥 길이({supported_context_length})를 초과했습니다.\"\n    )\n    \n    # 4. 패딩 (Padding)\n    # 설정한 max_length보다 문장이 짧을 경우, 남은 뒷부분을 pad_token_id로 채웁니다.\n    # 모델은 고정된 길이의 입력을 선호하기 때문입니다.\n    input_ids += [pad_token_id] * (max_length - len(input_ids))\n    \n    # 5. 텐서 변환 및 배치 차원 추가 (매우 중요!)\n    # 현재 input_ids는 [길이] 형태의 1차원 리스트입니다.\n    # 하지만 모델은 [배치 크기, 길이] 형태의 2차원 입력을 기대합니다.\n    # unsqueeze(0)을 통해 [1, 길이] 형태로 차원을 하나 늘려줍니다. (가짜 배치 생성)\n    input_tensor = torch.tensor(input_ids, device=device).unsqueeze(0) \n\n    # 6. 모델 추론 (Inference)\n    with torch.no_grad(): # 기울기 계산 끄기 (메모리 절약)\n        # 모델에 입력을 넣어 출력(Logits)을 얻습니다.\n        # [:, -1, :] : (모든 배치, 마지막 토큰, 모든 클래스) -> 분류를 위해 마지막 토큰만 사용\n        logits = model(input_tensor)[:, -1, :]\n    \n    # 7. 결과 해석\n    # argmax: 확률값 중 가장 큰 값의 인덱스(0 또는 1)를 뽑습니다.\n    # item(): 텐서 값을 파이썬 정수(int)로 변환합니다.\n    predicted_label = torch.argmax(logits, dim=-1).item()\n\n    # 8. 사람이 읽을 수 있는 결과 반환\n    # 1이면 \"스팸\", 0이면 \"스팸아님\" 리턴\n    return \"스팸\" if predicted_label == 1 else \"스팸아님\""}, {"cell_number": 116, "source": "text_1 = (\n    \"You are a winner you have been specially\"\n    \" selected to receive $1000 cash or a $2000 award.\"\n)\n\nprint(classify_review(\n    text_1, model, tokenizer, device, max_length=train_dataset.max_length\n))"}, {"cell_number": 117, "source": "text_2 = (\n    \"Hey, just wanted to check if we're still on\"\n    \" for dinner tonight? Let me know!\"\n)\n\nprint(classify_review(\n    text_2, model, tokenizer, device, max_length=train_dataset.max_length\n))"}, {"cell_number": 119, "source": "torch.save(model.state_dict(), \"outputs/review_classifier.pth\")"}, {"cell_number": 121, "source": "model_state_dict = torch.load(\"outputs/review_classifier.pth\", map_location=device, weights_only=True)\nmodel.load_state_dict(model_state_dict)"}], "blanks": [{"id": "blank-01", "number": 1, "answer": "[encoded_text[:self.max_length] for encoded_text in self.encoded_texts]", "prompt": "설정된 최대 길이만 남기도록 토큰 ID 리스트를 자르세요."}, {"id": "blank-02", "number": 2, "answer": "[encoded_text + [pad_token_id] * (self.max_length - len(encoded_text)) for encoded_text in self.encoded_texts]", "prompt": "부족한 길이만큼 pad_token_id를 뒤에 붙이세요."}, {"id": "blank-03", "number": 3, "answer": "self.data.iloc[index]['Label']", "prompt": "현재 샘플의 Label 컬럼을 가져오세요."}, {"id": "blank-04", "number": 4, "answer": "False", "prompt": "기반 GPT 전체를 학습 대상에서 제외하세요."}, {"id": "blank-05", "number": 5, "answer": "torch.nn.Linear(in_features=BASE_CONFIG['emb_dim'], out_features=num_classes)", "prompt": "GPT의 vocabulary 출력 head를 2개 클래스 분류 head로 바꾸세요."}, {"id": "blank-06", "number": 6, "answer": "True", "prompt": "마지막 Transformer Block을 다시 학습 가능하게 하세요."}, {"id": "blank-07", "number": 7, "answer": "True", "prompt": "최종 LayerNorm을 다시 학습 가능하게 하세요."}, {"id": "blank-08", "number": 8, "answer": "torch.nn.functional.cross_entropy(logits[:, -1, :], target_batch)", "prompt": "문장 분류용 마지막 token logits과 target_batch로 cross entropy loss를 계산하세요."}, {"id": "blank-09", "number": 9, "answer": "torch.nn.functional.cross_entropy(logits.flatten(0, 1), target_batch.flatten())", "prompt": "언어 모델링 분기에서는 모든 token 위치를 비교하도록 logits와 target을 flatten하세요."}]}, "llm-06b": {"chapterId": "llm-06b", "title": "06B · Classification Finetuning with LoRA · 전체 노트북 시험", "file": "Chapter_6_Finetuning_for_Text_Classification_LoRA_KR.ipynb", "instruction": "전체 노트북을 위에서 아래로 읽고, 각 빈칸이 요구하는 코드만 작성하세요. 답은 빈칸 번호 순서대로 독립적으로 채점됩니다.", "cells": [{"cell_number": 3, "source": "from importlib.metadata import version\n\npkgs = [\"matplotlib\",\n        \"numpy\",\n        \"tiktoken\",\n        \"torch\",\n        # \"tensorflow\", # OpenAI의 사전 훈련된 가중치를 로드하기 위함\n        \"pandas\"      # 데이터셋 로딩용\n       ]\nfor p in pkgs:\n    print(f\"{p} 버전: {version(p)}\")"}, {"cell_number": 11, "source": "# import urllib\nimport requests\nfrom pathlib import Path\nimport pandas as pd\nfrom previous_chapters import (\n    download_and_unzip_spam_data,\n    create_balanced_dataset,\n    random_split\n)\n\nurl = \"https://archive.ics.uci.edu/static/public/228/sms+spam+collection.zip\"\nzip_path = \"datas/sms_spam_collection.zip\"\nextracted_path = \"datas/sms_spam_collection\"\ndata_file_path = Path(extracted_path) / \"SMSSpamCollection.tsv\"\n\ntry:\n    download_and_unzip_spam_data(url, zip_path, extracted_path, data_file_path)\nexcept (requests.exceptions.RequestException, TimeoutError) as e:\n    print(f\"기본 URL 실패: {e}. 백업 URL 시도 중...\")\n    url = \"https://f001.backblazeb2.com/file/LLMs-from-scratch/sms%2Bspam%2Bcollection.zip\"\n    download_and_unzip_spam_data(url, zip_path, extracted_path, data_file_path)\n\ndf = pd.read_csv(data_file_path, sep=\"\\t\", header=None, names=[\"Label\", \"Text\"])\nbalanced_df = create_balanced_dataset(df)\nbalanced_df[\"Label\"] = balanced_df[\"Label\"].map({\"ham\": 0, \"spam\": 1})\n\ntrain_df, validation_df, test_df = random_split(balanced_df, 0.7, 0.1)\ntrain_df.to_csv(\"datas/train.csv\", index=None)\nvalidation_df.to_csv(\"datas/validation.csv\", index=None)\ntest_df.to_csv(\"datas/test.csv\", index=None)"}, {"cell_number": 12, "source": "import torch\nimport tiktoken\nfrom previous_chapters import SpamDataset\n\n\ntokenizer = tiktoken.get_encoding(\"gpt2\")\ntrain_dataset = SpamDataset(\"datas/train.csv\", max_length=None, tokenizer=tokenizer)\nval_dataset = SpamDataset(\"datas/validation.csv\", max_length=train_dataset.max_length, tokenizer=tokenizer)\ntest_dataset = SpamDataset(\"datas/test.csv\", max_length=train_dataset.max_length, tokenizer=tokenizer)"}, {"cell_number": 13, "source": "from torch.utils.data import DataLoader\n\nnum_workers = 0\nbatch_size = 8\n\ntorch.manual_seed(123)\n\ntrain_loader = DataLoader(\n    dataset=train_dataset,\n    batch_size=batch_size,\n    shuffle=True,\n    num_workers=num_workers,\n    drop_last=True,\n)\n\nval_loader = DataLoader(\n    dataset=val_dataset,\n    batch_size=batch_size,\n    num_workers=num_workers,\n    drop_last=False,\n)\n\ntest_loader = DataLoader(\n    dataset=test_dataset,\n    batch_size=batch_size,\n    num_workers=num_workers,\n    drop_last=False,\n)"}, {"cell_number": 15, "source": "print(\"훈련 로더:\")\nfor input_batch, target_batch in train_loader:\n    pass\n\nprint(\"입력 배치 차원:\", input_batch.shape)\nprint(\"레이블 배치 차원\", target_batch.shape)"}, {"cell_number": 17, "source": "print(f\"{len(train_loader)}개 훈련 배치\")\nprint(f\"{len(val_loader)}개 검증 배치\")\nprint(f\"{len(test_loader)}개 테스트 배치\")"}, {"cell_number": 20, "source": "from previous_chapters import GPTModel, load_gpt2_model\nCHOOSE_MODEL = \"gpt2-small (124M)\"\n\nBASE_CONFIG = {\n    \"vocab_size\": 50257,     # 어휘사전 크기\n    \"context_length\": 1024,  # 문맥 길이\n    \"drop_rate\": 0.0,        # 드롭아웃 비율\n    \"qkv_bias\": True         # 쿼리-키-값 편향\n}\n\nmodel_configs = {\n    \"gpt2-small (124M)\": {\"emb_dim\": 768, \"n_layers\": 12, \"n_heads\": 12}, #트랜스포머 블록(Transformer Block)을 몇 층으로 쌓아 올렸는지\n    \"gpt2-medium (355M)\": {\"emb_dim\": 1024, \"n_layers\": 24, \"n_heads\": 16},\n    \"gpt2-large (774M)\": {\"emb_dim\": 1280, \"n_layers\": 36, \"n_heads\": 20},\n    \"gpt2-xl (1558M)\": {\"emb_dim\": 1600, \"n_layers\": 48, \"n_heads\": 25},\n}\n\nBASE_CONFIG.update(model_configs[CHOOSE_MODEL])\n\nmodel_name = \"gpt2-small-124M.pth\"\nmodel = load_gpt2_model(model_name, BASE_CONFIG)\nmodel.eval()"}, {"cell_number": 22, "source": "from previous_chapters import (\n    generate_text_simple,\n    text_to_token_ids,\n    token_ids_to_text\n)\n\n\ntext_1 = \"Every effort moves you\"\n\ntoken_ids = generate_text_simple(\n    model=model,\n    idx=text_to_token_ids(text_1, tokenizer),\n    max_new_tokens=15,\n    context_size=BASE_CONFIG[\"context_length\"]\n)\n\nprint(token_ids_to_text(token_ids, tokenizer))"}, {"cell_number": 24, "source": "torch.manual_seed(123)\n\nnum_classes = 2\nmodel.out_head = torch.nn.Linear(in_features=768, out_features=num_classes)"}, {"cell_number": 25, "source": "if torch.cuda.is_available():\n    device = torch.device(\"cuda\")\n\nelse:\n    device = torch.device(\"cpu\")\n\nprint(\"사용 장치:\", device)\n\nmodel.to(device);  # nn.Module 클래스의 경우 model = model.to(device)와 같은 할당이 필요 없습니다."}, {"cell_number": 27, "source": "from previous_chapters import calc_accuracy_loader\n# 대안:\n# from llms_from_scratch.ch06 import calc_accuracy_loader\n\n\n\ntorch.manual_seed(123)\ntrain_accuracy = calc_accuracy_loader(train_loader, model, device, num_batches=10)\nval_accuracy = calc_accuracy_loader(val_loader, model, device, num_batches=10)\ntest_accuracy = calc_accuracy_loader(test_loader, model, device, num_batches=10)\n\nprint(f\"훈련 정확도: {train_accuracy*100:.2f}%\")\nprint(f\"검증 정확도: {val_accuracy*100:.2f}%\")\nprint(f\"테스트 정확도: {test_accuracy*100:.2f}%\")"}, {"cell_number": 30, "source": "import math\nimport torch\n\nclass LoRALayer(torch.nn.Module):\n    def __init__(self, in_dim, out_dim, rank, alpha):\n        \"\"\"\n        LoRA(Low-Rank Adaptation) 레이어 초기화\n        \n        Args:\n            in_dim: 입력 데이터의 차원 크기 (예: 768)\n            out_dim: 출력 데이터의 차원 크기 (예: 768)\n            rank: 병목 구간의 크기 (Rank, r). 작을수록 파라미터가 적어짐 (예: 8, 16)\n            alpha: 스케일링 상수. 학습된 값의 영향력을 조절함\n        \"\"\"\n        super().__init__()\n        \n        # 1. 행렬 A (Down-projection)\n        # 입력(in_dim)을 작은 차원(rank)으로 압축하는 가중치입니다.\n        # 파라미터로 등록하여 학습되도록 합니다.\n        self.A = ????  # [빈칸 01]\n        \n        # A는 무작위 값(Kaiming Uniform)으로 초기화합니다.\n        # 이렇게 해야 다양한 특징을 학습할 준비가 됩니다.\n        torch.nn.init.kaiming_uniform_(self.A, a=math.sqrt(5))\n        \n        # 2. 행렬 B (Up-projection)\n        # 압축된 정보(rank)를 다시 원래 출력 차원(out_dim)으로 복원하는 가중치입니다.\n        self.B = ????  # [빈칸 02]\n        \n        # 중요: B는 '0'으로 초기화합니다.\n        # 이유: 학습 시작 시점에는 A @ B의 결과가 0이 되어야 합니다.\n        # 그래야 LoRA를 붙여도 기존 모델의 원래 출력값에 아무런 영향을 주지 않은 채로 시작할 수 있습니다.\n        \n        self.alpha = ????  # [빈칸 03]\n        self.rank = rank\n\n    def forward(self, x):\n        \"\"\"\n        순전파(Forward) 단계: 입력 x에 대한 LoRA 변화량(Delta)을 계산\n        \"\"\"\n        # 1. 행렬 연산 (x @ A @ B)\n        # 입력 x를 A와 곱해 차원을 줄이고(압축), \n        # 그 결과를 다시 B와 곱해 차원을 늘립니다(복원).\n        # 연산 순서: (Batch, in) -> (Batch, rank) -> (Batch, out)\n        \n        # 2. 스케일링 (alpha / rank)\n        # 학습된 결과에 상수배를 해줍니다. \n        # alpha는 강도 조절, rank로 나누는 것은 rank값이 바뀌어도 \n        # 학습률(Learning Rate)을 크게 수정하지 않기 위한 정규화(Normalization) 과정입니다.\n        x = ????  # [빈칸 04]\n        \n        return x"}, {"cell_number": 33, "source": "import torch\n\nclass LinearWithLoRA(torch.nn.Module):\n    \"\"\"\n    기존의 Linear 레이어를 감싸서(Wrapping), \n    LoRA 어댑터를 추가한 새로운 복합 레이어를 만드는 클래스\n    \"\"\"\n    def __init__(self, linear, rank, alpha):\n        super().__init__()\n        \n        # 1. 기존 레이어 저장 (Frozen Weights)\n        # 이미 학습된 레이어 가중치(W)를 그대로 가져옵니다.\n        # 실제 사용 시에는 이 레이어의 가중치를 고정(freeze)시켜 학습되지 않게 합니다.\n        self.linear = linear\n        \n        # 2. LoRA 레이어 생성 (Trainable Adapter)\n        # 기존 레이어와 똑같은 입/출력 차원을 가지지만, 내부는 훨씬 가벼운 LoRA 레이어를 만듭니다.\n        # linear.in_features, linear.out_features: 기존 레이어의 스펙을 그대로 베껴옵니다.\n        self.lora = LoRALayer(\n            linear.in_features, linear.out_features, rank, alpha\n        )\n\n    def forward(self, x):\n        # 3. 결과 합치기 (The Core Logic)\n        # 원래 모델이 하던 계산 결과 : self.linear(x)\n        # LoRA가 새로 학습한 변화량 : self.lora(x)\n        # 최종 결과 = 원래 결과 + 변화량\n        return ????  # [빈칸 05]"}, {"cell_number": 36, "source": "import torch\n\ndef replace_linear_with_lora(model, rank, alpha):\n    \"\"\"\n    모델 내의 모든 Linear 레이어를 찾아 LoRA가 적용된 레이어로 교체하는 재귀 함수\n    \n    Args:\n        model: 수정할 파이토치 모델 (또는 모델의 하위 모듈)\n        rank: LoRA의 Rank (r)\n        alpha: LoRA의 Alpha (스케일링 계수)\n    \"\"\"\n    \n    # 1. 자식 모듈 순회 (Iterate Children)\n    # named_children(): 현재 모듈 바로 아래에 있는 구성 요소들을 (이름, 객체) 쌍으로 가져옵니다.\n    # 예: (\"attn\", AttentionModule), (\"mlp\", MLPModule) ...\n    for name, module in model.named_children():\n        \n        # 2. 교체 대상 확인 (Check Target)\n        # 현재 보고 있는 모듈이 'torch.nn.Linear'인지 확인합니다.\n        # (즉, 우리가 LoRA를 붙이고 싶은 기본 선형 층인지 확인)\n        if isinstance(module, torch.nn.Linear):\n            \n            # 3. 레이어 교체 (Swap Layer)\n            # setattr(객체, 속성이름, 새로운값): 객체의 속성을 동적으로 변경하는 파이썬 내장 함수\n            # model의 'name'에 해당하는 레이어를 -> 'LinearWithLoRA'로 덮어씌웁니다.\n            # 이때 기존 module을 인자로 넘겨줘서 가중치를 그대로 보존하게 합니다.\n            ????  # [빈칸 06]\n            \n        else:\n            # 4. 재귀 호출 (Dig Deeper)\n            # 만약 Linear 레이어가 아니라면(예: 트랜스포머 블록, 어텐션 층 등 컨테이너라면),\n            # 그 내부에도 Linear 레이어가 숨어있을 수 있으므로\n            # 그 안으로 들어가서 다시 똑같은 작업(replace_linear_with_lora)을 수행하라고 시킵니다.\n            ????  # [빈칸 07]"}, {"cell_number": 38, "source": "# 1. 현재 학습 가능한(Trainable) 파라미터 개수 계산\n# - model.parameters(): 모델 내부의 모든 가중치(W)와 편향(b)을 가져옵니다.\n# - p.numel(): 각 파라미터 텐서의 전체 원소 개수(Number of Elements)를 셉니다.\n# - if p.requires_grad: 현재 '학습 대상(True)'으로 설정된 것들만 필터링합니다.\ntotal_params = sum(p.numel() for p in model.parameters() if p.requires_grad)\n\n# {total_params:,} : 천 단위마다 쉼표(,)를 찍어서 보기 좋게 출력 (예: 1,000,000)\nprint(f\"이전의 총 학습 가능 파라미터 수: {total_params:,}\")\n\n\n# 2. 모든 파라미터 얼리기 (Freezing)\n# 모델의 모든 파라미터를 하나씩 꺼내서 반복합니다.\nfor param in model.parameters():\n    # requires_grad = False:\n    # \"이 파라미터는 이제 학습시키지 마(기울기 계산 X)\"라고 설정합니다.\n    # 이렇게 하면 역전파(Backpropagation) 때 이 값들은 업데이트되지 않고 고정됩니다.\n    param.requires_grad = ????  # [빈칸 08]\n\n\n# 3. 얼린 후 학습 가능 파라미터 수 재계산\n# 위에서 모든 param의 requires_grad를 False로 바꿨으므로, \n# 조건(if p.requires_grad)을 만족하는 파라미터가 하나도 없게 됩니다.\ntotal_params = sum(p.numel() for p in model.parameters() if p.requires_grad)\n\n# 결과적으로 0이 출력되어야 정상입니다.\nprint(f\"이후의 총 학습 가능 파라미터 수: {total_params:,}\")"}, {"cell_number": 39, "source": "replace_linear_with_lora(model, rank=16, alpha=16)\n\ntotal_params = sum(p.numel() for p in model.parameters() if p.requires_grad)\nprint(f\"총 학습 가능 LoRA 파라미터 수: {total_params:,}\")"}, {"cell_number": 41, "source": "model.to(device)\n\nprint(model)"}, {"cell_number": 43, "source": "torch.manual_seed(123)\ntrain_accuracy = calc_accuracy_loader(train_loader, model, device, num_batches=10)\nval_accuracy = calc_accuracy_loader(val_loader, model, device, num_batches=10)\ntest_accuracy = calc_accuracy_loader(test_loader, model, device, num_batches=10)\n\nprint(f\"훈련 정확도: {train_accuracy*100:.2f}%\")\nprint(f\"검증 정확도: {val_accuracy*100:.2f}%\")\nprint(f\"테스트 정확도: {test_accuracy*100:.2f}%\")"}, {"cell_number": 45, "source": "import time\nfrom previous_chapters import train_classifier_simple\n\nstart_time = time.time()\n\ntorch.manual_seed(123)\n\noptimizer = torch.optim.AdamW(model.parameters(), lr=8e-4, weight_decay=0.1)\n\nnum_epochs = 5\ntrain_losses, val_losses, train_accs, val_accs, examples_seen = train_classifier_simple(\n    model, train_loader, val_loader, optimizer, device,\n    num_epochs=num_epochs, eval_freq=50, eval_iter=5,\n)\n\nend_time = time.time()\nexecution_time_minutes = (end_time - start_time) / 60\nprint(f\"훈련이 {execution_time_minutes:.2f}분 만에 완료되었습니다.\")"}, {"cell_number": 48, "source": "from previous_chapters import plot_values\n# 대안:\n# from llms_from_scratch.ch06 import plot_values\n\nepochs_tensor = torch.linspace(0, num_epochs, len(train_losses))\nexamples_seen_tensor = torch.linspace(0, examples_seen, len(train_losses))\n\nplot_values(epochs_tensor, examples_seen_tensor, train_losses, val_losses, label=\"loss\")"}, {"cell_number": 50, "source": "train_accuracy = calc_accuracy_loader(train_loader, model, device)\nval_accuracy = calc_accuracy_loader(val_loader, model, device)\ntest_accuracy = calc_accuracy_loader(test_loader, model, device)\n\nprint(f\"훈련 정확도: {train_accuracy*100:.2f}%\")\nprint(f\"검증 정확도: {val_accuracy*100:.2f}%\")\nprint(f\"테스트 정확도: {test_accuracy*100:.2f}%\")"}], "blanks": [{"id": "blank-01", "number": 1, "answer": "torch.nn.Parameter(torch.empty(in_dim, rank))", "prompt": "입력 차원에서 rank로 가는 학습 행렬 A를 생성하고 초기화하세요."}, {"id": "blank-02", "number": 2, "answer": "torch.nn.Parameter(torch.zeros(rank, out_dim))", "prompt": "rank에서 출력 차원으로 가는 학습 행렬 B를 0으로 초기화하세요."}, {"id": "blank-03", "number": 3, "answer": "alpha", "prompt": "LoRA 변화량 크기를 조절할 alpha를 저장하세요."}, {"id": "blank-04", "number": 4, "answer": "self.alpha / self.rank * (x @ self.A @ self.B)", "prompt": "A와 B의 저랭크 변화량에 alpha/rank 스케일을 적용해 반환하세요."}, {"id": "blank-05", "number": 5, "answer": "self.linear(x) + self.lora(x)", "prompt": "기존 Linear 출력과 LoRA 변화량을 더해 반환하세요."}, {"id": "blank-06", "number": 6, "answer": "setattr(model, name, LinearWithLoRA(module, rank, alpha))", "prompt": "찾은 Linear 레이어를 기존 가중치를 보존하는 LinearWithLoRA로 교체하세요."}, {"id": "blank-07", "number": 7, "answer": "replace_linear_with_lora(module, rank, alpha)", "prompt": "컨테이너 레이어 내부까지 재귀적으로 탐색하세요."}, {"id": "blank-08", "number": 8, "answer": "False", "prompt": "LoRA 주입 전 기존 모델 파라미터를 모두 동결하세요."}]}};
